BEGIN;
CREATE TABLE "FinanceReportExport"(id UUID PRIMARY KEY,"requesterId" UUID NOT NULL REFERENCES "Person" ON DELETE RESTRICT,"requesterGrantId" UUID NOT NULL,"reportType" TEXT NOT NULL CHECK("reportType" IN('GENERAL_LEDGER','TRIAL_BALANCE','PROFIT_LOSS','BALANCE_SHEET','CASH_FLOW','RECEIVABLES_AGEING','PAYABLES_AGEING','ROLL_FORWARD','BUDGET_VARIANCE')),filters JSONB NOT NULL CHECK(jsonb_typeof(filters)='object'),mode TEXT NOT NULL CHECK(mode IN('REVIEW','FINAL')),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 500),state TEXT NOT NULL DEFAULT 'QUEUED' CHECK(state IN('QUEUED','RUNNING','READY','FAILED','CANCELLED','SUPERSEDED')),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3),"leaseId" UUID,"leaseUntil" TIMESTAMPTZ,snapshot JSONB,"snapshotHash" TEXT,csv BYTEA,pdf BYTEA,"csvHash" TEXT,"pdfHash" TEXT,"errorCode" TEXT,"failureDetails" JSONB CHECK("failureDetails" IS NULL OR octet_length("failureDetails"::text)<=32768),"supersededAt" TIMESTAMPTZ,"supersedeReason" TEXT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMPTZ NOT NULL,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK((state='RUNNING')=("leaseId" IS NOT NULL AND "leaseUntil" IS NOT NULL)),CHECK((snapshot IS NULL)=("snapshotHash" IS NULL)),CHECK(snapshot IS NULL OR(octet_length(snapshot::text)<=6291456 AND "snapshotHash"=encode(sha256(convert_to(snapshot::text,'UTF8')),'hex'))),CHECK((state IN('READY','SUPERSEDED'))=(csv IS NOT NULL AND pdf IS NOT NULL AND "csvHash" IS NOT NULL AND "pdfHash" IS NOT NULL)),CHECK(csv IS NULL OR(octet_length(csv) BETWEEN 1 AND 3145728 AND "csvHash"=encode(sha256(csv),'hex'))),CHECK(pdf IS NULL OR(octet_length(pdf) BETWEEN 1 AND 3145728 AND "pdfHash"=encode(sha256(pdf),'hex'))),CHECK(state NOT IN('READY','SUPERSEDED') OR snapshot IS NOT NULL),CHECK(state<>'SUPERSEDED' OR("supersededAt" IS NOT NULL AND "supersedeReason" IS NOT NULL AND length(trim("supersedeReason")) BETWEEN 3 AND 500)));
CREATE INDEX "FinanceReportExport_requesterId_createdAt_id_idx" ON "FinanceReportExport"("requesterId","createdAt",id);
CREATE INDEX "FinanceReportExport_state_leaseUntil_createdAt_idx" ON "FinanceReportExport"(state,"leaseUntil","createdAt");
CREATE FUNCTION encova_finance_export_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'FINANCE_EXPORT_RETAINED' USING ERRCODE='P0001';END IF;
 IF TG_OP='INSERT' THEN IF NEW.state<>'QUEUED' OR NEW.version<>1 OR NEW.attempts<>0 OR NEW.snapshot IS NOT NULL OR NEW.csv IS NOT NULL OR NEW.pdf IS NOT NULL THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;RETURN NEW;END IF;
 IF ROW(NEW.id,NEW."requesterId",NEW."requesterGrantId",NEW."reportType",NEW.filters,NEW.mode,NEW.reason,NEW."createdAt",NEW."expiresAt") IS DISTINCT FROM ROW(OLD.id,OLD."requesterId",OLD."requesterGrantId",OLD."reportType",OLD.filters,OLD.mode,OLD.reason,OLD."createdAt",OLD."expiresAt") OR NEW.version<>OLD.version+1 OR(OLD.snapshot IS NOT NULL AND NEW.snapshot IS DISTINCT FROM OLD.snapshot) OR(OLD."snapshotHash" IS NOT NULL AND NEW."snapshotHash" IS DISTINCT FROM OLD."snapshotHash") THEN RAISE EXCEPTION 'FINANCE_EXPORT_RETAINED' USING ERRCODE='P0001';END IF;
 IF NOT(OLD.state='RUNNING' AND NEW.state='RUNNING' AND NEW.attempts=OLD.attempts AND OLD.snapshot IS NULL AND NEW.snapshot IS NOT NULL AND ROW(NEW."leaseId",NEW."leaseUntil") IS NOT DISTINCT FROM ROW(OLD."leaseId",OLD."leaseUntil") OR OLD.state IN('QUEUED','FAILED','RUNNING') AND NEW.state='RUNNING' AND NEW.attempts=OLD.attempts+1 OR OLD.state='RUNNING' AND NEW.state IN('READY','FAILED','CANCELLED') AND NEW.attempts=OLD.attempts OR OLD.state IN('QUEUED','FAILED') AND NEW.state IN('QUEUED','CANCELLED') AND NEW.attempts=OLD.attempts OR OLD.state='READY' AND NEW.state='SUPERSEDED' AND NEW.attempts=OLD.attempts AND ROW(NEW.csv,NEW.pdf,NEW."csvHash",NEW."pdfHash") IS NOT DISTINCT FROM ROW(OLD.csv,OLD.pdf,OLD."csvHash",OLD."pdfHash")) THEN RAISE EXCEPTION 'FINANCE_EXPORT_RETAINED' USING ERRCODE='P0001';END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER "FinanceReportExport_guard" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceReportExport" FOR EACH ROW EXECUTE FUNCTION encova_finance_export_guard();
CREATE FUNCTION encova_finance_export_access(actor UUID,grant_id UUID DEFAULT NULL) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM public."Person" p JOIN public."FinanceGrant" g ON g."userId"=p.id AND g."revokedAt" IS NULL WHERE p.id=actor AND p.role='SUPER_ADMIN' AND p.status='ACTIVE' AND(grant_id IS NULL OR g.id=grant_id)) $$;
CREATE FUNCTION encova_finance_export_budget(input JSONB) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE target_month DATE;cutoff DATE;project_id UUID;result JSONB;BEGIN
 IF input-ARRAY['month','projectId']<>'{}'::jsonb OR jsonb_typeof(input->'month') IS DISTINCT FROM 'string' OR input->>'month'!~'^[0-9]{4}-(0[1-9]|1[0-2])$' OR jsonb_typeof(input->'projectId') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 target_month:=((input->>'month')||'-01')::date;IF target_month<DATE '0001-01-01' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;cutoff:=(target_month+interval '1 month'-interval '1 day')::date;project_id:=CASE WHEN input->>'projectId'='SHARED' THEN NULL ELSE(input->>'projectId')::uuid END;
 IF project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."Project" WHERE id=project_id) THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
 WITH plan AS(SELECT l."accountId",sum(l.amount) AS amount FROM public."FinanceBudgetLine" l JOIN public."FinanceBudget" b ON b.id=l."budgetId" WHERE b.month=target_month AND b."projectId" IS NOT DISTINCT FROM project_id AND b.state='APPROVED' GROUP BY l."accountId"),actual AS(SELECT l."accountId",sum(l.debit-l.credit) AS amount FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" JOIN public."FinanceAccount" a ON a.id=l."accountId" WHERE l."projectId" IS NOT DISTINCT FROM project_id AND e."postingDate">=target_month AND e."postingDate"<=cutoff AND e."sourceType"<>'YEAR_CLOSE' AND a.type IN('DIRECT_COST','OPERATING_EXPENSE','OTHER_EXPENSE') GROUP BY l."accountId"),ids AS(SELECT "accountId" FROM plan UNION SELECT "accountId" FROM actual),rows AS(SELECT a.id AS "accountId",a.code,a.name,(a.active AND a."isPosting" AND NOT a."isContra" AND a."controlType"='NONE' AND a.type IN('DIRECT_COST','OPERATING_EXPENSE','OTHER_EXPENSE')) AS "mappingAvailable",coalesce(p.amount,0) AS budget,coalesce(c.amount,0) AS actual,coalesce(p.amount,0)-coalesce(c.amount,0) AS remaining,(p."accountId" IS NULL AND coalesce(c.amount,0)<>0) AS unbudgeted,(coalesce(c.amount,0)>coalesce(p.amount,0)) AS exceeded FROM ids JOIN public."FinanceAccount" a ON a.id=ids."accountId" LEFT JOIN plan p ON p."accountId"=a.id LEFT JOIN actual c ON c."accountId"=a.id)
 SELECT jsonb_build_object('metadata',public.encova_finance_report_metadata(target_month,cutoff,jsonb_build_object('report','BUDGET_VARIANCE','month',input->>'month','projectId',input->>'projectId','budget',(SELECT jsonb_build_object('id',id,'number',number,'revision',revision,'version',version,'approvedAt',"approvedAt") FROM public."FinanceBudget" b WHERE b.month=target_month AND "projectId" IS NOT DISTINCT FROM project_id AND state='APPROVED'))),'filters',input,'budget',(SELECT jsonb_build_object('id',id,'number',number,'revision',revision,'version',version,'approvedAt',"approvedAt") FROM public."FinanceBudget" b WHERE b.month=target_month AND b."projectId" IS NOT DISTINCT FROM project_id AND b.state='APPROVED'),'advisoryOnly',true,'items',coalesce(jsonb_agg((to_jsonb(r)-ARRAY['budget','actual','remaining'])||jsonb_build_object('budget',round(r.budget,2)::text,'actual',round(r.actual,2)::text,'remaining',round(r.remaining,2)::text) ORDER BY r.code,r."accountId"),'[]'::jsonb),'total',count(*),'totals',jsonb_build_object('budget',round(coalesce(sum(r.budget),0),2)::text,'actual',round(coalesce(sum(r.actual),0),2)::text,'remaining',round(coalesce(sum(r.remaining),0),2)::text)) INTO result FROM rows r;RETURN result;
END $$;
CREATE FUNCTION encova_finance_export_page(actor UUID,report_type TEXT,filters JSONB,requested_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF jsonb_typeof(filters) IS DISTINCT FROM 'object' OR filters ?| ARRAY['page','issuePage','rowKey','actorId','readiness','finalExportEligible'] THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF report_type IN('GENERAL_LEDGER','TRIAL_BALANCE') THEN RETURN public.encova_finance_report_core(actor,report_type,filters||jsonb_build_object('page',requested_page));
 ELSIF report_type IN('PROFIT_LOSS','BALANCE_SHEET') THEN RETURN public.encova_finance_statement_report(actor,report_type,filters||jsonb_build_object('page',requested_page,'issuePage',1));
 ELSIF report_type='CASH_FLOW' THEN RETURN public.encova_finance_cash_flow_read(actor,'REPORT',filters||jsonb_build_object('page',requested_page));
 ELSIF report_type IN('RECEIVABLES_AGEING','PAYABLES_AGEING') THEN RETURN public.encova_finance_ageing_read(actor,CASE WHEN report_type='RECEIVABLES_AGEING' THEN 'REPORT_AR' ELSE 'REPORT_AP' END,filters||jsonb_build_object('page',requested_page,'issuePage',1));
 ELSIF report_type='ROLL_FORWARD' THEN RETURN public.encova_finance_rollforward_read(actor,filters->>'kind','REPORT',(filters-'kind')||jsonb_build_object('page',requested_page,'issuePage',1));
 ELSIF report_type='BUDGET_VARIANCE' THEN RETURN public.encova_finance_export_budget(filters);
 END IF;RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END $$;
CREATE FUNCTION encova_finance_export_readiness(date_from DATE,cutoff DATE) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE statement JSONB;ar JSONB;ap JSONB;cash JSONB;r JSONB;rolls JSONB:='{}'::jsonb;kind TEXT;bank_count INTEGER;missing_banks INTEGER;missing_cash INTEGER;bank_issues JSONB;bank_proofs JSONB;deferred_issues INTEGER;clearing NUMERIC;closed_count INTEGER;ready BOOLEAN;BEGIN
 statement:=public.encova_finance_statement_readiness(date_from,cutoff,1);
 ar:=public.encova_finance_ageing_report('AR',cutoff,'',1,1,false,'ALL')->'reconciliation';ap:=public.encova_finance_ageing_report('AP',cutoff,'',1,1,false,'ALL')->'reconciliation';cash:=public.encova_finance_cash_flow_report(date_from,cutoff,'',1);
 FOREACH kind IN ARRAY ARRAY['FUNDING','LOANS','INVESTMENTS','ASSETS','ADVANCES'] LOOP r:=public.encova_finance_rollforward_report(kind,DATE '0001-01-01',cutoff,'',1,1)->'reconciliation';rolls:=rolls||jsonb_build_object(kind,r);END LOOP;
 WITH banks AS MATERIALIZED(SELECT b.id,b.name,b."glAccountId",r.id AS review_id FROM public."FinanceCashAccount" b LEFT JOIN public."FinanceReconciliation" r ON r."cashAccountId"=b.id AND r."cutoffDate"=cutoff AND r.state='FINAL' WHERE b.active OR EXISTS(SELECT 1 FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE l."accountId"=b."glAccountId" AND e."postingDate"<=cutoff))
 SELECT count(*),count(*) FILTER(WHERE review_id IS NULL),coalesce(jsonb_agg(jsonb_build_object('cashAccountId',id,'name',name,'issue','FINAL_BANK_RECONCILIATION_REQUIRED') ORDER BY id) FILTER(WHERE review_id IS NULL),'[]'::jsonb),coalesce(jsonb_agg(jsonb_build_object('cashAccountId',id,'reconciliationId',review_id) ORDER BY id) FILTER(WHERE review_id IS NOT NULL),'[]'::jsonb) INTO bank_count,missing_banks,bank_issues,bank_proofs FROM banks;
 SELECT count(*) INTO missing_cash FROM public."FinanceAccount" a WHERE a."controlType"='CASH' AND EXISTS(SELECT 1 FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE l."accountId"=a.id AND e."postingDate"<=cutoff) AND NOT EXISTS(SELECT 1 FROM public."FinanceCashAccount" b WHERE b."glAccountId"=a.id);
 SELECT count(*) INTO deferred_issues FROM public."FinanceAccount" a WHERE a."controlType"='DEFERRED_REVENUE' AND coalesce((SELECT sum(l.credit-l.debit) FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE l."accountId"=a.id AND e."postingDate"<=cutoff),0)<>coalesce((SELECT sum(v.amount) FROM public."FinanceDeferredRevenueEvent" v JOIN public."FinanceInvoiceLine" l ON l.id=v."invoiceLineId" WHERE l."deferredAccountId"=a.id AND v."effectiveDate"<=cutoff),0);
 SELECT coalesce(sum(abs(balance)),0) INTO clearing FROM public.encova_finance_statement_balances(cutoff) WHERE "controlType"='OPENING_CLEARING';
 SELECT count(*) INTO closed_count FROM public."FinancePeriod" WHERE state='CLOSED' AND daterange("startDate","endDate",'[]') && daterange(date_from,cutoff,'[]');
 ready:=(statement->>'finalExportEligible')::boolean AND(ar->>'ready')::boolean AND(ap->>'ready')::boolean AND(cash->>'classificationReady')::boolean AND missing_banks=0 AND missing_cash=0 AND deferred_issues=0 AND clearing=0 AND closed_count=0 AND cutoff<=(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Karachi')::date AND NOT EXISTS(SELECT 1 FROM jsonb_each(rolls)x WHERE NOT(x.value->>'ready')::boolean);
 RETURN jsonb_build_object('finalEligible',ready,'scope','Full company book, presentation, bank, AR/AP, deferred revenue, roll-forward and cash-component checks; never reduced by display filters','presentation',statement,'receivables',ar,'payables',ap,'rollforwards',rolls,'cashFlow',jsonb_build_object('classificationReady',cash->'classificationReady','unclassifiedCount',cash->'unclassifiedCount','difference',cash->'difference','componentDigest',cash#>'{metadata,filters,componentDigest}'),'banks',jsonb_build_object('total',bank_count,'missing',missing_banks,'missingCashMasters',missing_cash,'issues',(SELECT coalesce(jsonb_agg(v),'[]'::jsonb) FROM(SELECT value AS v FROM jsonb_array_elements(bank_issues) LIMIT 25)b),'proofs',bank_proofs),'deferredControlIssueCount',deferred_issues,'openingClearingBalance',round(clearing,2)::text,'closedPeriodCount',closed_count,'futureCutoff',cutoff>(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Karachi')::date);
END $$;
CREATE FUNCTION encova_finance_export_capture(actor UUID,report_type TEXT,filters JSONB,export_mode TEXT) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE first_page JSONB;part JSONB;rows JSONB;readiness JSONB;date_from DATE;cutoff DATE;pages INTEGER;n INTEGER;BEGIN
 first_page:=public.encova_finance_export_page(actor,report_type,filters,1);IF (first_page->>'total')::integer>2000 THEN RAISE EXCEPTION 'FINANCE_EXPORT_LIMIT' USING ERRCODE='P0001';END IF;
 date_from:=(first_page#>>'{metadata,from}')::date;cutoff:=(first_page#>>'{metadata,to}')::date;IF date_from IS NULL OR cutoff IS NULL THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 readiness:=public.encova_finance_export_readiness(date_from,cutoff);
 rows:=coalesce(first_page->'items','[]'::jsonb);pages:=CASE WHEN report_type='BUDGET_VARIANCE' THEN 1 ELSE coalesce((first_page->>'pages')::integer,1) END;
 IF pages>80 THEN RAISE EXCEPTION 'FINANCE_EXPORT_LIMIT' USING ERRCODE='P0001';END IF;
 FOR n IN 2..pages LOOP part:=public.encova_finance_export_page(actor,report_type,filters,n);rows:=rows||(part->'items');END LOOP;
 IF jsonb_array_length(rows) IS DISTINCT FROM(first_page->>'total')::integer THEN RAISE EXCEPTION 'FINANCE_EXPORT_INCONSISTENT' USING ERRCODE='P0001';END IF;
 RETURN jsonb_build_object('schemaVersion',1,'reportType',report_type,'filters',filters,'mode',export_mode,'readiness',readiness,'report',jsonb_set(first_page,'{items}',rows),'rowCount',jsonb_array_length(rows),'frozen',true);
END $$;
CREATE FUNCTION encova_finance_export_command(actor UUID,provider TEXT,session_id TEXT,verified_at TIMESTAMPTZ,action TEXT,input JSONB,request_key TEXT,request_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE job public."FinanceReportExport"%ROWTYPE;receipt public."FinanceLedgerReceipt"%ROWTYPE;grant_id UUID;digest TEXT;result JSONB;checked JSONB;BEGIN
 IF action IS NULL OR action NOT IN('REQUEST','RETRY','CANCEL') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR request_key IS NULL OR length(request_key) NOT BETWEEN 8 AND 128 OR jsonb_typeof(input->'reason') IS DISTINCT FROM 'string' OR length(trim(input->>'reason')) NOT BETWEEN 3 AND 500 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF verified_at IS NULL OR verified_at<CURRENT_TIMESTAMP-interval '5 minutes' OR verified_at>CURRENT_TIMESTAMP+interval '5 seconds' THEN RAISE EXCEPTION 'FINANCE_REAUTH_REQUIRED' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(987661);PERFORM public.encova_finance_lock_person(actor);
 IF NOT public.encova_finance_export_access(actor) OR NOT public.encova_finance_session_ok(actor,provider,session_id) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(629815);SELECT id INTO grant_id FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL;
 digest:=encode(sha256(convert_to(input::text,'UTF8')),'hex');SELECT * INTO receipt FROM public."FinanceLedgerReceipt" WHERE "actorId"=actor AND operation='EXPORT_'||action AND key=request_key;
 IF receipt.id IS NOT NULL THEN IF receipt."requestHash"<>digest THEN RAISE EXCEPTION 'FINANCE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;RETURN receipt.result;END IF;
 IF action='REQUEST' THEN
  IF input-ARRAY['reportType','filters','mode','reason']<>'{}'::jsonb OR jsonb_typeof(input->'reportType') IS DISTINCT FROM 'string' OR jsonb_typeof(input->'mode') IS DISTINCT FROM 'string' OR input->>'mode' NOT IN('REVIEW','FINAL') OR jsonb_typeof(input->'filters') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  checked:=public.encova_finance_export_page(actor,input->>'reportType',input->'filters',1);
  INSERT INTO public."FinanceReportExport"(id,"requesterId","requesterGrantId","reportType",filters,mode,reason,"expiresAt") VALUES(gen_random_uuid(),actor,grant_id,input->>'reportType',input->'filters',input->>'mode',trim(input->>'reason'),CURRENT_TIMESTAMP+interval '24 hours') RETURNING * INTO job;
 ELSE
  IF input-ARRAY['id','expectedVersion','reason']<>'{}'::jsonb OR jsonb_typeof(input->'id') IS DISTINCT FROM 'string' OR jsonb_typeof(input->'expectedVersion') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT * INTO job FROM public."FinanceReportExport" WHERE id=(input->>'id')::uuid FOR UPDATE;
  IF job.id IS NULL OR job."requesterId"<>actor OR job."requesterGrantId"<>grant_id THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
  IF job.version<>(input->>'expectedVersion')::integer THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF action='RETRY' THEN
   IF job.state<>'FAILED' OR job.attempts>=3 OR job."expiresAt"<=CURRENT_TIMESTAMP THEN RAISE EXCEPTION 'FINANCE_EXPORT_STATE' USING ERRCODE='P0001';END IF;
   UPDATE public."FinanceReportExport" SET state='QUEUED',version=version+1,"errorCode"=NULL,"updatedAt"=CURRENT_TIMESTAMP WHERE id=job.id RETURNING * INTO job;
  ELSE
   IF job.state NOT IN('QUEUED','FAILED','RUNNING') THEN RAISE EXCEPTION 'FINANCE_EXPORT_STATE' USING ERRCODE='P0001';END IF;
   UPDATE public."FinanceReportExport" SET state='CANCELLED',version=version+1,"errorCode"='CANCELLED_BY_REQUESTER',"leaseId"=NULL,"leaseUntil"=NULL,"updatedAt"=CURRENT_TIMESTAMP WHERE id=job.id RETURNING * INTO job;
  END IF;
 END IF;
 result:=jsonb_build_object('id',job.id,'version',job.version,'state',job.state);
 INSERT INTO public."FinanceLedgerReceipt"(id,"actorId",operation,key,"requestHash",result) VALUES(gen_random_uuid(),actor,'EXPORT_'||action,request_key,digest,result);
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),actor,'FINANCE_EXPORT_'||action,'FinanceReportExport',job.id,trim(input->>'reason'),jsonb_build_object('state',job.state,'version',job.version,'reportType',job."reportType",'mode',job.mode,'nonposting',true),request_id);RETURN result;
 EXCEPTION WHEN data_exception OR check_violation OR foreign_key_violation OR not_null_violation THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END $$;
CREATE FUNCTION encova_finance_export_claim(target UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE job public."FinanceReportExport"%ROWTYPE;snap JSONB;token UUID;code TEXT;BEGIN
 PERFORM pg_advisory_xact_lock(987661);SELECT * INTO job FROM public."FinanceReportExport" WHERE id=target;IF job.id IS NULL THEN RETURN NULL;END IF;
 PERFORM public.encova_finance_lock_person(job."requesterId");PERFORM pg_advisory_xact_lock(629815);SELECT * INTO job FROM public."FinanceReportExport" WHERE id=target FOR UPDATE;
 IF job.state NOT IN('QUEUED','FAILED','RUNNING') OR(job.state='RUNNING' AND job."leaseUntil">CURRENT_TIMESTAMP) THEN RETURN NULL;END IF;
 IF job.attempts>=3 THEN IF job.state='RUNNING' THEN UPDATE public."FinanceReportExport" SET state='FAILED',version=version+1,"leaseId"=NULL,"leaseUntil"=NULL,"errorCode"='FINANCE_EXPORT_ATTEMPTS',"updatedAt"=CURRENT_TIMESTAMP WHERE id=target;END IF;RETURN NULL;END IF;
 IF NOT public.encova_finance_export_access(job."requesterId",job."requesterGrantId") OR job."expiresAt"<=CURRENT_TIMESTAMP THEN
  UPDATE public."FinanceReportExport" SET state='CANCELLED',version=version+1,"leaseId"=NULL,"leaseUntil"=NULL,"errorCode"=CASE WHEN job."expiresAt"<=CURRENT_TIMESTAMP THEN 'EXPORT_EXPIRED' ELSE 'ACCESS_REVOKED' END,"updatedAt"=CURRENT_TIMESTAMP WHERE id=target;RETURN NULL;
 END IF;
 token:=gen_random_uuid();UPDATE public."FinanceReportExport" SET state='RUNNING',version=version+1,attempts=attempts+1,"leaseId"=token,"leaseUntil"=CURRENT_TIMESTAMP+interval '60 seconds',"errorCode"=NULL,"updatedAt"=CURRENT_TIMESTAMP WHERE id=target RETURNING * INTO job;
 BEGIN
  IF job.snapshot IS NULL THEN snap:=public.encova_finance_export_capture(job."requesterId",job."reportType",job.filters,job.mode);ELSE snap:=job.snapshot;END IF;
  IF octet_length(snap::text)>6291456 THEN RAISE EXCEPTION 'FINANCE_EXPORT_LIMIT' USING ERRCODE='P0001';END IF;
  IF job.mode='FINAL' AND (NOT(snap#>>'{readiness,finalEligible}')::boolean OR EXISTS(SELECT 1 FROM public."FinancePeriod" WHERE state='CLOSED' AND daterange("startDate","endDate",'[]') && daterange((snap#>>'{report,metadata,from}')::date,(snap#>>'{report,metadata,to}')::date,'[]'))) THEN
   UPDATE public."FinanceReportExport" SET state='FAILED',version=version+1,"leaseId"=NULL,"leaseUntil"=NULL,"errorCode"='FINANCE_EXPORT_INCOMPLETE',"failureDetails"=CASE WHEN octet_length((snap->'readiness')::text)<=32768 THEN snap->'readiness' ELSE jsonb_build_object('finalEligible',false,'issue','Review company report controls and bank reconciliations; diagnostics exceed the bounded summary') END,"updatedAt"=CURRENT_TIMESTAMP WHERE id=target;RETURN NULL;
  END IF;
  IF job.snapshot IS NULL THEN UPDATE public."FinanceReportExport" SET snapshot=snap,"snapshotHash"=encode(sha256(convert_to(snap::text,'UTF8')),'hex'),version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=target RETURNING * INTO job;END IF;
 EXCEPTION WHEN OTHERS THEN
  code:=CASE WHEN SQLERRM IN('FINANCE_EXPORT_LIMIT','FINANCE_EXPORT_INCONSISTENT','FINANCE_INVALID_INPUT','FINANCE_NOT_FOUND') THEN SQLERRM ELSE 'FINANCE_EXPORT_PREPARATION' END;
  UPDATE public."FinanceReportExport" SET state='FAILED',version=version+1,"leaseId"=NULL,"leaseUntil"=NULL,"errorCode"=code,"updatedAt"=CURRENT_TIMESTAMP WHERE id=target;RETURN NULL;
 END;
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),job."requesterId",'FINANCE_EXPORT_CAPTURE','FinanceReportExport',job.id,'Capture frozen authorized report',jsonb_build_object('snapshotHash',job."snapshotHash",'attempt',job.attempts,'mode',job.mode),gen_random_uuid());
 RETURN jsonb_build_object('id',job.id,'leaseId',token,'snapshotHash',job."snapshotHash",'snapshot',job.snapshot);
END $$;
CREATE FUNCTION encova_finance_export_finish(target UUID,token UUID,snapshot_hash TEXT,csv_bytes BYTEA,pdf_bytes BYTEA,failure_code TEXT DEFAULT NULL) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE job public."FinanceReportExport"%ROWTYPE;allowed BOOLEAN;BEGIN
 PERFORM pg_advisory_xact_lock(987661);SELECT * INTO job FROM public."FinanceReportExport" WHERE id=target;IF job.id IS NULL THEN RETURN false;END IF;PERFORM public.encova_finance_lock_person(job."requesterId");PERFORM pg_advisory_xact_lock(629815);SELECT * INTO job FROM public."FinanceReportExport" WHERE id=target FOR UPDATE;
 IF job.state<>'RUNNING' OR job."leaseId" IS DISTINCT FROM token OR job."leaseUntil"<=CURRENT_TIMESTAMP OR job."snapshotHash" IS DISTINCT FROM snapshot_hash THEN RETURN false;END IF;
 allowed:=public.encova_finance_export_access(job."requesterId",job."requesterGrantId") AND job."expiresAt">CURRENT_TIMESTAMP;
 IF NOT allowed THEN UPDATE public."FinanceReportExport" SET state='CANCELLED',version=version+1,"leaseId"=NULL,"leaseUntil"=NULL,"errorCode"='ACCESS_REVOKED_OR_EXPIRED',"updatedAt"=CURRENT_TIMESTAMP WHERE id=target;RETURN false;END IF;
 IF failure_code IS NOT NULL THEN
  UPDATE public."FinanceReportExport" SET state='FAILED',version=version+1,"leaseId"=NULL,"leaseUntil"=NULL,"errorCode"=CASE WHEN failure_code IN('FINANCE_EXPORT_LIMIT','FINANCE_EXPORT_RENDER') THEN failure_code ELSE 'FINANCE_EXPORT_RENDER' END,"updatedAt"=CURRENT_TIMESTAMP WHERE id=target;RETURN false;
 END IF;
 IF job.mode='FINAL' AND EXISTS(SELECT 1 FROM public."FinancePeriod" WHERE state='CLOSED' AND daterange("startDate","endDate",'[]') && daterange((job.snapshot#>>'{report,metadata,from}')::date,(job.snapshot#>>'{report,metadata,to}')::date,'[]')) THEN UPDATE public."FinanceReportExport" SET state='FAILED',version=version+1,"leaseId"=NULL,"leaseUntil"=NULL,"errorCode"='FINANCE_EXPORT_CLOSED_PERIOD',"updatedAt"=CURRENT_TIMESTAMP WHERE id=target;RETURN false;END IF;
 IF csv_bytes IS NULL OR pdf_bytes IS NULL OR octet_length(csv_bytes) NOT BETWEEN 1 AND 3145728 OR octet_length(pdf_bytes) NOT BETWEEN 1 AND 3145728 OR substring(pdf_bytes FROM 1 FOR 5)<>convert_to('%PDF-','UTF8') THEN RAISE EXCEPTION 'FINANCE_EXPORT_LIMIT' USING ERRCODE='P0001';END IF;
 UPDATE public."FinanceReportExport" SET state='READY',version=version+1,"leaseId"=NULL,"leaseUntil"=NULL,csv=csv_bytes,pdf=pdf_bytes,"csvHash"=encode(sha256(csv_bytes),'hex'),"pdfHash"=encode(sha256(pdf_bytes),'hex'),"errorCode"=NULL,"failureDetails"=NULL,"updatedAt"=CURRENT_TIMESTAMP WHERE id=target;
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),job."requesterId",'FINANCE_EXPORT_READY','FinanceReportExport',job.id,'Prepare private CSV and PDF artifacts',jsonb_build_object('snapshotHash',snapshot_hash,'csvHash',encode(sha256(csv_bytes),'hex'),'pdfHash',encode(sha256(pdf_bytes),'hex')),gen_random_uuid());RETURN true;
END $$;
-- Only checked server operations are exposed. Jobs never expose artifacts to PostgreSQL public roles.
CREATE FUNCTION encova_finance_export_read(actor UUID,action TEXT,input JSONB) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE job public."FinanceReportExport"%ROWTYPE;page INTEGER;total INTEGER;owner BOOLEAN;result JSONB;BEGIN
 IF NOT public.encova_finance_export_access(actor) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 owner:=EXISTS(SELECT 1 FROM public."FinanceSettings" WHERE "ownerId"=actor);
 IF action='LIST' THEN
  IF input-ARRAY['page']<>'{}'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;page:=coalesce((input->>'page')::integer,1);IF page NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT count(*) INTO total FROM public."FinanceReportExport" j WHERE(owner OR j."requesterId"=actor) AND public.encova_finance_export_access(j."requesterId",j."requesterGrantId");
  SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t."createdAt" DESC,t.id DESC),'[]'::jsonb) INTO result FROM(SELECT j.id,j."reportType",j.mode,j.state,j.version,j.attempts,j."createdAt",j."expiresAt",j."errorCode",j."snapshotHash",j.snapshot->'rowCount' AS "rowCount" FROM public."FinanceReportExport" j WHERE(owner OR j."requesterId"=actor) AND public.encova_finance_export_access(j."requesterId",j."requesterGrantId") ORDER BY j."createdAt" DESC,j.id DESC LIMIT 25 OFFSET(page-1)*25)t;
  RETURN jsonb_build_object('items',result,'total',total,'page',page,'pages',greatest(1,ceil(total/25.0)::integer));
 END IF;
 IF action<>'DETAIL' OR input-ARRAY['id','page']<>'{}'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 page:=coalesce((input->>'page')::integer,1);IF page NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 SELECT * INTO job FROM public."FinanceReportExport" WHERE id=(input->>'id')::uuid;
 IF job.id IS NULL OR NOT(owner OR job."requesterId"=actor) OR NOT public.encova_finance_export_access(job."requesterId",job."requesterGrantId") THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
 total:=coalesce((job.snapshot->>'rowCount')::integer,0);
 result:=to_jsonb(job)-ARRAY['csv','pdf','leaseId','leaseUntil','snapshot','requesterGrantId'];
 RETURN result||jsonb_build_object('expired',job."expiresAt"<=CURRENT_TIMESTAMP,'canMutate',job."requesterId"=actor,'rowCount',total,'page',page,'pages',greatest(1,ceil(total/25.0)::integer),'readiness',job.snapshot->'readiness','metadata',job.snapshot#>'{report,metadata}','summary',(job.snapshot->'report')-ARRAY['items','metadata','page','pages'],'items',(SELECT coalesce(jsonb_agg(value ORDER BY ordinality),'[]'::jsonb) FROM jsonb_array_elements(coalesce(job.snapshot#>'{report,items}','[]'::jsonb)) WITH ORDINALITY WHERE ordinality BETWEEN (page-1)*25+1 AND page*25));
 EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END $$;
CREATE FUNCTION encova_finance_export_download(actor UUID,target UUID,format TEXT) RETURNS BYTEA LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE job public."FinanceReportExport"%ROWTYPE;BEGIN
 IF NOT public.encova_finance_export_access(actor) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 SELECT * INTO job FROM public."FinanceReportExport" WHERE id=target;
 IF format NOT IN('csv','pdf') OR job.id IS NULL OR NOT(job."requesterId"=actor OR EXISTS(SELECT 1 FROM public."FinanceSettings" WHERE "ownerId"=actor)) OR NOT public.encova_finance_export_access(job."requesterId",job."requesterGrantId") THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
 IF job.state<>'READY' OR job."expiresAt"<=CURRENT_TIMESTAMP THEN RAISE EXCEPTION 'FINANCE_EXPORT_STATE' USING ERRCODE='P0001';END IF;
 RETURN CASE WHEN format='csv' THEN job.csv ELSE job.pdf END;
END $$;
CREATE FUNCTION encova_finance_export_candidates() RETURNS SETOF UUID LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT id FROM public."FinanceReportExport" WHERE state='QUEUED' OR(state='RUNNING' AND "leaseUntil"<=CURRENT_TIMESTAMP) ORDER BY "createdAt",id LIMIT 3 $$;
ALTER TABLE "FinanceReportExport" ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE f RECORD;r TEXT;BEGIN
 FOR f IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'encova_finance_export_%' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
  FOREACH r IN ARRAY ARRAY['anon','authenticated','encova_app'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r);END IF;END LOOP;
 END LOOP;
 FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON "FinanceReportExport" FROM %I',r);END IF;END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN
  GRANT SELECT ON "FinanceReportExport" TO encova_app;CREATE POLICY encova_server_read ON "FinanceReportExport" FOR SELECT TO encova_app USING(true);
  GRANT EXECUTE ON FUNCTION encova_finance_export_command(UUID,TEXT,TEXT,TIMESTAMPTZ,TEXT,JSONB,TEXT,UUID),encova_finance_export_claim(UUID),encova_finance_export_finish(UUID,UUID,TEXT,BYTEA,BYTEA,TEXT),encova_finance_export_candidates(),encova_finance_export_read(UUID,TEXT,JSONB),encova_finance_export_download(UUID,UUID,TEXT) TO encova_app;
 END IF;
END $$;
COMMIT;
